window.ScripturaLexicons.BDAG_PART_0301 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-01\" data-source=\"BDAG\" data-search=\"προί̈ημι verbo emitir, exteriorizar, expressar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προί̈ημι</td><td>verbo</td><td>emitir, exteriorizar, expressar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-02\" data-source=\"BDAG\" data-search=\"πρόϊμος, ον adjetivo temporão, cedo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόϊμος, ον</td><td>adjetivo</td><td>temporão, cedo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-03\" data-source=\"BDAG\" data-search=\"προϊνός adjetivo variante de πρωϊνός BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προϊνός</td><td>adjetivo</td><td>variante de πρωϊνός</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-04\" data-source=\"BDAG\" data-search=\"προί̈στημι verbo liderar, administrar, cuidar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προί̈στημι</td><td>verbo</td><td>liderar, administrar, cuidar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-05\" data-source=\"BDAG\" data-search=\"προκάθημαι verbo presidir, exercer preeminência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκάθημαι</td><td>verbo</td><td>presidir, exercer preeminência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-06\" data-source=\"BDAG\" data-search=\"προκαλέω verbo provocar, desafiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκαλέω</td><td>verbo</td><td>provocar, desafiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-07\" data-source=\"BDAG\" data-search=\"προκαταγγέλλω verbo anunciar de antemão, predizer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκαταγγέλλω</td><td>verbo</td><td>anunciar de antemão, predizer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-08\" data-source=\"BDAG\" data-search=\"προκαταρτίζω verbo aprontar de antemão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκαταρτίζω</td><td>verbo</td><td>aprontar de antemão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-09\" data-source=\"BDAG\" data-search=\"προκατέχω verbo apoderar-se anteriormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκατέχω</td><td>verbo</td><td>apoderar-se anteriormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-10\" data-source=\"BDAG\" data-search=\"πρόκειμαι verbo depoente estar exposto, estar diante, estar em perspectiva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόκειμαι</td><td>verbo depoente</td><td>estar exposto, estar diante, estar em perspectiva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-11\" data-source=\"BDAG\" data-search=\"προκηρύσσω verbo proclamar publicamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκηρύσσω</td><td>verbo</td><td>proclamar publicamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-12\" data-source=\"BDAG\" data-search=\"προκοιμάομαι verbo adormecer anteriormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκοιμάομαι</td><td>verbo</td><td>adormecer anteriormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-13\" data-source=\"BDAG\" data-search=\"προκοπή, ῆς, ἡ substantivo feminino progresso, avanço BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκοπή, ῆς, ἡ</td><td>substantivo feminino</td><td>progresso, avanço</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-14\" data-source=\"BDAG\" data-search=\"προκόπτω verbo avançar, progredir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκόπτω</td><td>verbo</td><td>avançar, progredir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-15\" data-source=\"BDAG\" data-search=\"πρόκριμα, ατος, τό substantivo neutro prejulgamento, discriminação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόκριμα, ατος, τό</td><td>substantivo neutro</td><td>prejulgamento, discriminação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-16\" data-source=\"BDAG\" data-search=\"προκρίνω verbo preferir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκρίνω</td><td>verbo</td><td>preferir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-17\" data-source=\"BDAG\" data-search=\"προκυρόω verbo ratificar de antemão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προκυρόω</td><td>verbo</td><td>ratificar de antemão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-18\" data-source=\"BDAG\" data-search=\"προλαμβάνω verbo antecipar, empreender, surpreender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προλαμβάνω</td><td>verbo</td><td>antecipar, empreender, surpreender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-19\" data-source=\"BDAG\" data-search=\"προλέγω verbo dizer de antemão, declarar anteriormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προλέγω</td><td>verbo</td><td>dizer de antemão, declarar anteriormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0301-20\" data-source=\"BDAG\" data-search=\"προμαρτύρομαι verbo depoente dar testemunho de antemão, predizer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προμαρτύρομαι</td><td>verbo depoente</td><td>dar testemunho de antemão, predizer</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0301-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προί̈ημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προί̈ημι</span> fut. médio <span class=\"greek\">προήσομαι</span>; aor. médio inf. <span class=\"greek\">προέσθαι</span> Pr 17:27, subj. <span class=\"greek\">προῶμαι</span> Job 27:6 (Hom. et al.; ins, pap, LXX, Philo, Joseph.; Ar. 15:10) em nossa literatura somente na voz média: emitir de si mesmo, exteriorizar, expressar (Demosth. 19, 118 <span class=\"greek\">ῥῆμα</span>; Ps.-Pla., Tim. Locr. 100c <span class=\"greek\">λόγον</span>; Jos., C. Ap. 1, 43 <span class=\"greek\">ῥῆμα</span>) <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> algo a alguém (Alciphron 3, 18, 3) <span class=\"greek\">προήσομαι</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἐμῆς</span> <span class=\"greek\">πνοῆς</span> <span class=\"greek\">ῥῆσιν</span> 1 Cl 57:3 (Pr 1:23).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόϊμος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόϊμος</span>, <span class=\"greek\">ον</span> (a grafia padrão é <span class=\"greek\">πρώϊμος</span> [X., Oec. 17, 4 e outros; OGI 56, 68 <span class=\"greek\">πρώϊμος</span> <span class=\"greek\">σπόρος</span>: III a.C.; PTebt 27, 25; 76: 113 a.C.; L-S-J-M s.v.; DGeorgacas, ClPh 76, ’81, 156; v. a nota de RPfeiffer em Callimachus I ’49, 392, sobre Fgm. 550/482]; sobre o uso na LXX v. Thackeray p. 90.—B-D-F §35, 1; Mlt-H. 73). O substantivo (v. B-D-F §241, 5; W-S. §5, 19) <span class=\"greek\">πρόϊμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7</a> (oposto a <span class=\"greek\">ὄψιμος</span>; v. aparato de Tdf. sobre a leitura <span class=\"greek\">πρώϊμον</span>, e acrescente-se P74) é geralmente entendido no sentido de chuva temporã, de acordo com o t.r. e muitos manuscritos que acrescentam <span class=\"greek\">ὑετός</span> (Hollmann, Windisch, MDibelius, et al., com referência a Dt 11:14; Hos 6:3; Jo 2:23; Zech 10:1; Jer 5:24.). Outros pensam nas primeiras colheitas com base na v.l. <span class=\"greek\">πρ</span>(<span class=\"greek\">ό</span>)<span class=\"greek\">ϊμον</span> <span class=\"greek\">καρπόν</span> (cf. Petosiris, Fgm. 6, linha 45 <span class=\"greek\">πρώϊμοι</span> <span class=\"greek\">καρποί</span>; Geopon. 1, 12, 32 <span class=\"greek\">οἱ</span> <span class=\"greek\">πρώϊμοι</span> <span class=\"greek\">καρποὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄψιμοι</span>).—Em B 3:4, <span class=\"greek\">τότε</span> <span class=\"greek\">ῥαγήσεται</span> <span class=\"greek\">πρόϊμον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">σου</span> é citado de Is 58:8. A LXX talvez tivesse traduzido melhor o original hebraico com <span class=\"greek\">πρωϊνός</span>, mas parece provável que o tradutor quisesse dizer ‘cedo’=logo.—DELG s.v. <span class=\"greek\">πρώην</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προϊνός</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προϊνός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:28</a> v.l.; 22:16 v.l. é provavelmente uma grafia incorreta de <span class=\"greek\">πρωϊνός</span> (v. esse verbete).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προί̈στημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προί̈στημι</span> (Hom.+; ins, pap, LXX, TestJos 2:6; Joseph.; Just.; Mel., P. 42, 288 [Bo.]: ‘vir para diante’) em nossa literatura somente intransitivo; pres. e imperf. médios; também inf. do 2.º aor. <span class=\"greek\">προστῆναι</span>; perf. 3.ª pl. <span class=\"greek\">προεστήκασιν</span> 4 Macc 11:27, <span class=\"greek\">προεστᾶσιν</span> Dg 5:3, part. <span class=\"greek\">προεστηκώς</span> LXX, <span class=\"greek\">προεστώς</span> Pr 26:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:17</a> (também Just.). Forma alternativa <span class=\"greek\">προιστανόμενος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:8</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:12</a> v.l. (v. B-D-F 93, 1).</p><p class=\"entry-text\">① exercer uma posição de liderança, governar, dirigir, estar à frente (de), com gen. de pessoa ou coisa (Hdt., Thu. et al.; ins, pap; Am 6:10; 1 Macc 5:19), administrar, conduzir <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἰδίου</span> <span class=\"greek\">οἴκου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:4f</a>. <span class=\"greek\">τέκνων</span>, <span class=\"greek\">οἴκων</span> v. 12. A respeito de dirigentes e administradores nas congregações (cf. Diod S 40, 3, 4 a respeito de homens aptos <span class=\"greek\">δυνησομένους</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σύμπαντος</span> <span class=\"greek\">ἔθνους</span> [=<span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span>] <span class=\"greek\">προί̈στασθαι</span>; Jos., Ant. 8, 300 <span class=\"greek\">πρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλήθους</span>, Vi. 168). Assim talvez (v. 2 abaixo) <span class=\"greek\">οἱ</span> <span class=\"greek\">προϊστάμενοι</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:12</a> e, em uso absoluto, <span class=\"greek\">ὁ</span> <span class=\"greek\">προϊστάμενος</span> (cf. Jos., Vi. 93) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:8</a> (v. 2 abaixo). Certamente <span class=\"greek\">οἱ</span> <span class=\"greek\">καλῶς</span> <span class=\"greek\">προεστῶτες</span> <span class=\"greek\">πρεσβύτεροι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:17</a> (v. Nicol. Dam.: 90 Fgm. 130, 28 p. 414, 2 Jac. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κοινοῦ</span> <span class=\"greek\">προεστῶτες</span>; Plut., Mor. 304a <span class=\"greek\">οἱ</span> <span class=\"greek\">προεστῶτες</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πολιτείας</span>; Just., A I, 65, 3 e outros). <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">προϊστάμενοι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκκλησίας</span> Hv 2, 4, 3.—HGreeven, ZNW 44, ’52/53, 31–41.</p><p class=\"entry-text\">② ter interesse em, mostrar solicitude por, cuidar de, prestar auxílio (Demosth. 4, 46; Epict. 3, 24, 3; PFay 13, 5; PTebt 326, 11 <span class=\"greek\">τοῦ</span> <span class=\"greek\">παιδίου</span>; BGU 1105, 6; EpArist 182; Jos., Ant. 14, 196 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδικουμένων</span>) com gen. <span class=\"greek\">δόγματος</span> <span class=\"greek\">ἀνθρωπίνου</span> Dg 5:3 (para o sentido de ‘defender’ algo v. Aeschin. 2, 161 a paz). Assim talvez (v. 1) <span class=\"greek\">οἱ</span> <span class=\"greek\">προϊστάμενοι</span> <span class=\"greek\">ὑμῶν</span> (entre <span class=\"greek\">κοπιῶντες</span> e <span class=\"greek\">νουθετοῦντες</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:12</a> e <span class=\"greek\">ὁ</span> <span class=\"greek\">προϊστάμενος</span> (entre <span class=\"greek\">μεταδιδούς</span> e <span class=\"greek\">ἐλεῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:8</a> (v. vDobschütz sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:12</a> e o excurso após 5:13; contra ele vHarnack, ZNW 27, 1928, 7–10). Ocupar-se de, dedicar-se a, com gen. (Soph., Elect. 980 <span class=\"greek\">φόνου</span>; Athen. 13, 612a <span class=\"greek\">τέχνης</span>; Ep. 53 de Apolônio de Tiana [Philostrat. I 358, 8] <span class=\"greek\">προϊστάμενοι</span> <span class=\"greek\">φιλοσοφίας</span>; Pr 26:17; Jos., Ant. 5, 90; nas ins frequentemente a respeito de serviço público, p. ex. IPriene 50, 14f) <span class=\"greek\">καλῶν</span> <span class=\"greek\">ἔργων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:8</a>, 14 (cf. SIG 593, 5f <span class=\"greek\">προεστηκότες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐνδόξου</span>, como indicação de mérito excepcional).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκάθημαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκάθημαι</span> (Hdt. et al.; ins)</p><p class=\"entry-text\">① ocupar um cargo de liderança, presidir (a), dirigir (Pla. et al.; Polyb. 12, 16, 6; Plut., Rom. 14, 5; Cass. Dio 49, 40 et al.; SIG 694, 50f [129 a.C.] <span class=\"greek\">προκαθημέναις</span> <span class=\"greek\">θεαῖς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόλεως</span>; UPZ 110, 165 [164 a.C.]; 1 Esdr). Literalmente a respeito do <span class=\"greek\">ἐπίσκοπος</span> IMg 6:1. A respeito de outros dirigentes eclesiásticos além do superintendente/bispo <span class=\"greek\">οἱ</span> <span class=\"greek\">προκαθήμενοι</span> os dirigentes 6:2. A respeito da congregação romana <span class=\"greek\">προκάθηται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τόπῳ</span> (v. <span class=\"greek\">τύπος</span>, final) <span class=\"greek\">χωρίου</span> <span class=\"greek\">Ῥωμαίων</span> ela preside na terra dos romanos IRo ins a (v. sobre isto Lghtf. e Hdb. ad loc.; Harnack, SBBerlAk 1896, 111–31; JChapman, Rev. Bénéd. 13, 1896, 385ff; FFunk, Kirchengeschichtl. Abhandlungen u. Untersuchungen I 1897, 1–23; HAchelis, Das Christentum in den ersten drei Jahrhunderten 1912, I 210ff).</p><p class=\"entry-text\">② exercer preeminência, tomar a dianteira, extensão figurada de 1: a respeito da igreja romana <span class=\"greek\">προκαθημένη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀγάπης</span> preeminente no amor IRo ins b (v. AJülicher, GGA 1898, 4).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκαλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκαλέω</span> principalmente na voz média (Hom. et al.; ins, pap; 2 Macc 8:11; Jos., Ant. 7, 315; 18, 369; Just., D. 123, 7; Tat. 23, 1) chamar alguém para que venha à frente, frequentemente em sentido hostil: provocar, desafiar <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:26</a> (Diod S 4, 17, 4 <span class=\"greek\">προκαλεῖσθαί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μάχην</span>; Arrian, Cyneg. 16, 1; Lucian, Conv. 20 <span class=\"greek\">ἐς</span> <span class=\"greek\">ἀγῶνα</span> <span class=\"greek\">προκαλέσασθαι</span> <span class=\"greek\">αὐτόν</span>).—M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκαταγγέλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκαταγγέλλω</span> 1.º aor. <span class=\"greek\">προκατήγγειλα</span>; part. perf. pass. <span class=\"greek\">προκατηγγελμένος</span> (Jos., Ant. 1, 219; 2, 218) anunciar de antemão, predizer, a respeito de enunciado profético <span class=\"greek\">τὶ</span> algo (Jos., Ant. 10, 67) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:24</a> v.l. Acus. de coisa seguido de inf. aor. (B-D-F §350; 397, 3; Rob. 1036) 3:18. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> dar informação acerca de algo de antemão, isto é, predizer algo 7:52. Voz passiva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:5</a> v.l.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκαταρτίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκαταρτίζω</span> 1.º aor. subj. <span class=\"greek\">προκαταρτίσω</span> (Hippocr. et al.) aprontar, tomar providências antecipadamente para <span class=\"greek\">τὶ</span> algo (SEG IV, 449, 13 [II a.C.] <span class=\"greek\">λίθους</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:5</a>.—Frisk s.v. <span class=\"greek\">ἄρτι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκατέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκατέχω</span> (Hom. Hymns, Thu. et al.; pap; Jos., Bell. 4, 503) apoderar-se anteriormente ou ocupar anteriormente <span class=\"greek\">τὶ</span> algo, fig. (cf. Polyb. 8, 33, 3 <span class=\"greek\">προκατέχεσθαι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Ῥωμαίους</span> <span class=\"greek\">εὐνοίᾳ</span>; 27, 4, 9) <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προκατεχόντων</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιαν</span> <span class=\"greek\">λογισμῶν</span>=(purifica-te) de todos os pensamentos que se apoderaram de tua mente até agora Dg 2:1. A palavra também se encontra em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:9</a> v.l. <span class=\"greek\">προκατέχομεν</span> <span class=\"greek\">περισσόν</span>; temos uma vantagem prévia? (v. <span class=\"greek\">προέχω</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόκειμαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόκειμαι</span> (Hom.+; primariamente ‘estar posto diante de alguém’) depoente defectivo.</p><p class=\"entry-text\">① estar exposto à vista pública, estar exposto (a respeito de cadáveres expostos solenemente Aeschyl., Sept. 965 e outros) a respeito de Sodoma e Gomorra <span class=\"greek\">πρόκεινται</span> <span class=\"greek\">δεῖγμα</span> estão expostas como exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 7</a> (cf. Jos., Bell. 6, 103 <span class=\"greek\">καλὸν</span> <span class=\"greek\">ὑπόδειγμα</span> <span class=\"greek\">πρόκειται</span>).</p><p class=\"entry-text\">② estar presente diante de alguém, estar diante, estar presente (Ps.-Clem., Hom. 3, 51) <span class=\"greek\">ἡ</span> <span class=\"greek\">προθυμία</span> <span class=\"greek\">πρόκειται</span> há disposição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:12</a> (com <span class=\"greek\">ἐπιτελεῖν</span> [v. v. 11], cf. SIG 671 B5 a respeito da boa vontade real). <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">προκειμένης</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">χαρᾶς</span> em lugar de (<span class=\"greek\">ἀντί</span> 1) a alegria que estava posta diante dele, isto é, em lugar da alegria que estava ao seu alcance, ele suportou a cruz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:2</a> (ERiggenbach; JNisius, Zur Erklärung v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:2</a>: BZ 14, 1917, 44–61); v. também 3 abaixo. <span class=\"greek\">ἡ</span> <span class=\"greek\">προκειμένη</span> <span class=\"greek\">ἐλπίς</span> a esperança que está posta diante de nós 6:18 (cf. Jos., Ant. 1, 14 <span class=\"greek\">εὐδαιμονία</span> <span class=\"greek\">πρόκειταί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span>). <span class=\"greek\">πρόκειται</span> está diante (de nós), isto é, essa é a questão em pauta (Diod S 8, 11, 4; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 2, 3; 16, 1; Just., A II, 9, 5 <span class=\"greek\">τὸ</span> <span class=\"greek\">προκείμενον</span>=o assunto em discussão) IPhld 8:2. <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">μικρὸς</span> <span class=\"greek\">ἀγὼν</span> <span class=\"greek\">πρόκειται</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">σοῦ</span> não é pequena a controvérsia a teu respeito GJs 20:11 (códices; para a formulação v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:1</a> abaixo).</p><p class=\"entry-text\">③ situar-se, como perspectiva, depois de determinado momento, a respeito de uma meta ou destino, com dat. de pessoa: estar ou ser posto diante de alguém (Ael. Aristid. 31, 2 K.=11 p. 127 D.: <span class=\"greek\">μητρὶ</span> <span class=\"greek\">πένθος</span> <span class=\"greek\">πρόκειται</span>; Ath. 18, 1 <span class=\"greek\">οὐ</span> … <span class=\"greek\">προκείμενον</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐλέγχειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">εἴδωλα</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">προκείμενος</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">σκοπός</span> a meta que está posta diante de nós 1 Cl 63:1 (v. <span class=\"greek\">σκοπός</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">προκείμενος</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ἀγών</span> (v. <span class=\"greek\">ἀγών</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:1</a>. Sem dat. (Diod S 4, 42, 7) IMg 5:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">προκείμενον</span> <span class=\"greek\">ζῆν</span> a vida que está posta diante (de vós) IEph 17:1.—Também estar em perspectiva (Jos., Ant. 1, 14; 8, 208.—Diod S 15, 60, 1 [um prêmio] e <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> p. 66, 20 V. a respeito de salários que foram concedidos; Tat. 23, 1): assim talvez (v. 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:2</a>: pela (<span class=\"greek\">ἀντί</span> 1 e 3) alegria que estava em perspectiva para ele (assim Windisch2, Strathmann; cf. Moffatt; NRSV).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκηρύσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκηρύσσω</span> 1.º aor. 3.ª sing., pl. <span class=\"greek\">προεκήρυξε</span>,-<span class=\"greek\">ξαν</span> (Just.); part. <span class=\"greek\">προκηρύξας</span>; mais-que-perfeito 3.ª sing. <span class=\"greek\">προκεκηρύχει</span> (Just., D. 78, 6). Voz passiva: aor. 3.ª sing. <span class=\"greek\">προκεκηρύχθη</span> (Mel., P. 39, 275), part. acus. sing. <span class=\"greek\">προκηρυχθέντα</span> (Just., A I, 58, 1); part. perf. <span class=\"greek\">προκεκηρυγμένος</span>, inf. <span class=\"greek\">προκεκηρύχθαι</span> (assim Just., A I, 52, 1); mais-que-perfeito 3.ª sing. <span class=\"greek\">προκεκεκήρυκτο</span> (Just., A I, 36, 3 e outros) (desde Soph.; X., De Rep. Lac. 11, 2; ins, pap, Philo, Joseph.; Just., Mel.) em nossa literatura o prefixo <span class=\"greek\">προ</span> evidentemente dá à palavra o sentido de proclamar publicamente (Lucian, Tyrannic. 9; Alex. Aphr., An. p. 1, 6 Br.; Jos., Bell. 6, 385) <span class=\"greek\">τὶ</span> algo, a respeito de João Batista <span class=\"greek\">βάπτισμα</span> <span class=\"greek\">μετανοίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:24</a>. A respeito dos profetas do AT (Jos., Ant. 10, 79 <span class=\"greek\">Ἰερεμίας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλλοντα</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πόλει</span> <span class=\"greek\">προεκήρυξε</span>; Just., D. 84, 2 [a respeito de Isaías] e outros) <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔλευσιν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> Pol 6:3. Voz passiva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:20</a> v.l. (em lugar de <span class=\"greek\">προκεχειρισμένον</span>).—DELG s.v. <span class=\"greek\">κῆρυξ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκοιμάομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκοιμάομαι</span> part. perf. pass. <span class=\"greek\">προκεκοιμημένος</span> adormecer antes de um ponto de referência temporal, adormecer antes ou anteriormente, eufemismo para ter morrido anteriormente (v. <span class=\"greek\">κοιμάω</span> 2, <span class=\"greek\">προοδοιπορέω</span>; Cat. Cod. Astr. VIII/3, 110; Leontius 45 p. 94, 18) <span class=\"greek\">προκεκοιμημένοι</span> aqueles que adormeceram anteriormente Hs 9, 16, 5f.—DELG s.v. <span class=\"greek\">κεῖμαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκοπή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκοπή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Polyb.+; Bion em Diog. L. 4, 50; Posidonius em Diog. L. 7, 91; Diod S 16, 6, 3; Epict. [índice Sch.]; OGI 627, 2; PRyl 233, 16; PGiss 27, 7; PMert 24, 9f; Sir 51:17; 2 Macc 8:8; EpArist 242; Philo; Jos., Ant. 4, 59; Test12Patr; empréstimo no rabínico. Rejeitada pelos aticistas: Phryn. p. 85 Lob.; Theoph. Ant. 2, 24 [p. 158, 16]) movimento para diante em direção a um estado melhor, progresso, avanço, desenvolvimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:15</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τινος</span> <span class=\"greek\">ἔρχεσθαι</span> contribuir para o avanço de algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:12</a>.—New Docs 4, 36. DELG s.v. <span class=\"greek\">κόπτω</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκόπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκόπτω</span> (Eur., Hdt. et al.) em nossa literatura somente intransitivo (Polyb. et al.; ins, pap; Ps 44:5 Sym.; TestJud 21:8; Philo, Joseph., Just.) imperf. <span class=\"greek\">προέκοπτον</span>; fut. <span class=\"greek\">προκόψω</span>; 1.º aor. <span class=\"greek\">προέκοψα</span>.</p><p class=\"entry-text\">① avançar em direção a uma etapa final, a respeito do tempo: estar avançado, estar muito adiantado (Chariton 2, 3, 9; Appian, Bell. Civ. 2, 78 §325 <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">προύκοπτεν</span>; Just., D. 56, 16) <span class=\"greek\">ἡ</span> <span class=\"greek\">νὺξ</span> <span class=\"greek\">προέκοψεν</span> (Jos., Bell. 4, 298) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:12</a>.</p><p class=\"entry-text\">② avançar em direção a um estado melhor, progredir, avançar no que é bom ou no que é mau <span class=\"greek\">τινί</span> em algo (Diod S 11, 87, 5; SIG 708, 18 [II a.C.] <span class=\"greek\">ἡλικίᾳ</span> <span class=\"greek\">προκόπτων</span>; Philo, Sacr. Abel. 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:52</a> v.l. Também <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (Diod S 17, 69, 4; Epict. 2, 17, 4; Lucian, Hermot. 63; M. Ant. 1, 17, 8; Vett. Val. 60, 15; 19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:52</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰουδαϊσμῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:14</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐντολαῖς</span> 2 Cl 17:3; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πλεῖον</span> <span class=\"greek\">πρ</span>. (Diod S 14, 98, 3) progredir ainda mais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:9</a>; seguido de gen. (Ael. Aristid. 46 p. 405 D. <span class=\"greek\">τ</span>. <span class=\"greek\">σοφίας</span>) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πλεῖον</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀσεβείας</span> 2:16 (cf. Jos., Ant. 20, 205). <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χεῖρον</span> ir de mal a pior 3:13 (Paroem. Gr.: Zenob. 3, 82 <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χεῖρον</span> <span class=\"greek\">προκοπτόντων</span>; Jos., Bell. 6, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">πάθη</span> <span class=\"greek\">προύκοπτεν</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χεῖρον</span>, Ant. 4, 59; 18, 340; TestJud 21:8 v.l. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κακόν</span>; escólio a Soph., El. 875 p. 142 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βέλτιον</span>).—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόκριμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόκριμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">προκρίνω</span>; como termo técnico jurídico IG V/1, 21 II, 7 [II a.C.]; Mitt-Wilck. II/2, 88 II, 30) julgamento que envolve tomar partido de antemão, prejulgamento, discriminação <span class=\"greek\">χωρὶς</span> <span class=\"greek\">πρ</span>. (PFlor 68, 13; 16f três vezes) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:21</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκρίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκρίνω</span> aor. <span class=\"greek\">προέκρινα</span> Wsd 7:8; perf. pass. <span class=\"greek\">προκέκριμαι</span> (Eur., Hdt.; ins, pap, Wsd 7:8; Just., D. 5, 5; Mel., HE 4, 26, 13) fazer uma escolha com base em uma preferência, preferir <span class=\"greek\">τινός</span> a algo (Herm. Wr. 4, 8a) voz passiva: ser preferido (Arrian, Anab. 1, 16, 4; Mitt-Wilck. I/2, 27, 6 [II d.C.] <span class=\"greek\">προκρίνονται</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">οὑτινοσοῦν</span> [conj. de Schubart em lugar de <span class=\"greek\">οὗτινος</span> <span class=\"greek\">οὐχ</span>] <span class=\"greek\">οἱ</span> <span class=\"greek\">νόμοι</span> as leis prevalecem sobre qualquer outra coisa [como decretos]; Philo, Cher. 46; Jos., Ant. 11, 196; 18, 46) a respeito da fé e do amor <span class=\"greek\">ὧν</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">προκέκριται</span> aos quais nada é preferível ou superior ISm 6:1 (Diog. L. 1, 82 <span class=\"greek\">Βίας</span> <span class=\"greek\">προκεκριμένος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἑπτά</span>=Bías, que superava os demais dos sete [sábios]); cf. IMg 1:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προκυρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προκυρόω</span> part. perf. pass. <span class=\"greek\">προκεκυρωμένος</span> tornar válido/ratificar de antemão (SEG III, 674A, 28 [II a.C.]) <span class=\"greek\">διαθήκη</span> <span class=\"greek\">προκεκυρωμένη</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> um testamento ou aliança (<span class=\"greek\">διαθήκη</span> 1) anteriormente ratificado por Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:17</a>.—New Docs 4, 171. DELG s.v. <span class=\"greek\">κύριος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προλαμβάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προλαμβάνω</span> 2.º aor. <span class=\"greek\">προέλαβον</span>; 1.º aor. pass. <span class=\"greek\">προελήμφθην</span> (sobre a grafia v. B-D-F §101 p. 53; Mlt-H. 246f) (Trag., Hdt.+; ins, pap, LXX, EpArist; SibOr 3, 569; Philo, Joseph., Just.; Ath., R. 25 p. 78, 23) primariamente ‘tomar de antemão’.</p><p class=\"entry-text\">① fazer algo que envolve algum elemento de prioridade temporal</p><p class=\"entry-text\">ⓐ com o valor temporal de <span class=\"greek\">προ</span> bastante acentuado <span class=\"greek\">πρ</span>. <span class=\"greek\">τι</span> fazer algo antes do tempo habitual, antecipar algo (cf. Theophr., HP 8, 1, 4 <span class=\"greek\">πρ</span>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">εὐδίαις</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αὔξησιν</span> ‘iniciar o crescimento de antemão em condições meteorológicas favoráveis’; IG XIV, 2014, 1; Philo, Somn. 1, 2; Just., D. 131, 4 <span class=\"greek\">πάντα</span> [a respeito de Deus]) seguido de infinitivo (Jos., Ant. 6, 305; B-D-F §392, 2; Rob. 1120) <span class=\"greek\">προέλαβεν</span> <span class=\"greek\">μυρίσαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμά</span> <span class=\"greek\">μου</span> ela ungira meu corpo de antemão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:8</a>.</p><p class=\"entry-text\">ⓑ com o valor temporal de <span class=\"greek\">προ</span> ainda perceptível: tomar sobre si, empreender (no sentido de ‘antecipar mentalmente’ em Polyb. e Plut.; EpArist 206; seguido de inf. Hippocr., Ep. 27, 41) <span class=\"greek\">προέλαβον</span> <span class=\"greek\">παρακαλεῖν</span> <span class=\"greek\">ὑμᾶς</span> IEph 3:2.</p><p class=\"entry-text\">ⓒ tomar, obter, a respeito de uma refeição (SIG 1170, 7; 9; 15 a respeito do consumo de alimentos [<span class=\"greek\">ἄρτον</span>, <span class=\"greek\">γάλα</span> et al.] no templo de Asclépio em Epidauro. V. também vWilamowitz na nota 4 à ins) provavelmente com o valor temporal de <span class=\"greek\">προ</span> perceptível em certa medida <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">δεῖπνον</span> <span class=\"greek\">προλαμβάνει</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φαγεῖν</span> ao comer, cada um se adianta para tomar a própria ceia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:21</a> (v. <span class=\"greek\">ἴδιος</span> 1b).</p><p class=\"entry-text\">② descobrir algo de surpresa, detectar, alcançar, surpreender <span class=\"greek\">τινά</span> alguém (TestJud 2:5 perseguir e alcançar um javali) voz passiva (POxy 928, 8; Wsd 17:16) <span class=\"greek\">ἐὰν</span> <span class=\"greek\">προλημφθῇ</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">παραπτώματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>. V. Field, Notes 190; JRobb, ET 57, ’45/46, 222.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προλέγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προλέγω</span> perf. pass. 3.ª sing. <span class=\"greek\">προλέλεκται</span> (Aeschyl., Hdt.+; ins; Is 41:26; TestSol; GrBar 8:7; EpArist 8; Just., Tat.).</p><p class=\"entry-text\">① dizer algo antes de um acontecimento, dizer de antemão/antecipadamente (Demetr. de Falero [300 a.C.]: 228 Fgm. 39 Jac. p. 970, 2f <span class=\"greek\">τὶς</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">προὔλεγε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέλλον</span>; Apollon. Paradox. 3 <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλλοντα</span>; TestSol 10:10 C; Jos., Ant. 7, 226; cf. CB I/2 p. 386 n.º 232, 8: Gaio, um advogado, antes de sua morte exprime seus pensamentos em um epitáfio para seu túmulo; v. <span class=\"greek\">προεῖπον</span> 1) seguido de <span class=\"greek\">ὅτι</span> (Pla., Rep. 1, 337a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:21</a> (correspondendo às palavras <span class=\"greek\">προλέγω</span> <span class=\"greek\">καθὼς</span> <span class=\"greek\">προεῖπον</span>, Appian, Bell. Civ. 2, 139 §579 traz a expressão dupla <span class=\"greek\">προλέγομεν</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">προεροῦμεν</span>); em advertência (Nicol. Dam.: 90 Fgm. 130, 97 Jac.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:4</a> (na passagem supramencionada de Appian, Bruto diz <span class=\"greek\">προλέγομεν</span> ‘nós’, como Paulo diz <span class=\"greek\">προελέγομεν</span>). A respeito de um enunciado profético <span class=\"greek\">προλέγει</span> <span class=\"greek\">ἡμῖν</span> (segue-se uma citação de Is) 1 Cl 34:3 (Appian, Bell. Civ. 1. 71 §326 os sacerdotes encarregados dos sacrifícios predizem o que há de acontecer; Just., D. 41, 3 [de Mal.]).</p><p class=\"entry-text\">② dizer/expressar algo em um momento anterior a outro momento, declarar de antemão/anteriormente (<span class=\"greek\">προεῖπον</span> 2b) perf. pass. <span class=\"greek\">ὡς</span> <span class=\"greek\">προλέλεκται</span> conforme foi declarado acima (Ps.-Demetr., Eloc. 89) EpilMosq 5.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0301-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προμαρτύρομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προμαρτύρομαι</span> depoente médio (PLond IV, 1356, 32 [710 d.C.]) falar com solene segurança acerca de algo que há de acontecer, dar testemunho de antemão, predizer <span class=\"greek\">τὶ</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:11</a> (a forma na v.l. de <span class=\"greek\">προμαρτυρέομαι</span> encontra-se em PLond IV, 1343, 27 [709 d.C.]).—DELG s.v. <span class=\"greek\">μάρτυς</span>. M-M. TW.</p></section></article>"};
